function splitColor(i, total){
  if(total === 8) return (i === 2 || i === 3 || i === 6 || i === 7) ? "brown" : "";
  if(total === 9) return (i % 2 === 1) ? "brown" : "";
  return i >= Math.ceil(total / 2) ? "brown" : "";
}
function splitCardClass(i, total){
  return splitColor(i, total);
}
