        ${card("Execution capability","Accounting, tax, payroll, controlling, CFO support, financing and automation in one model.","03")}
        ${card("More Time for Business","Owners and boards focus on sales, product and market development instead of daily finance supervision.","04",true)}
        ${card("Better Decisions","Key choices are based on reliable models, scenarios and clear recommendations.","05")}
        ${card("Predictable Profit & Liquidity","Budgets, forecasts and cash-flow projections reduce surprises and support safer growth.","06",true)}
        ${card("Lower Risk","Structured processes and standards reduce tax, accounting and operational risk.","07")}
        ${card("Financing Readiness","Transparent data and reporting make it easier to raise debt, equity or prepare for sale.","08",true)}
        ${card("CFO Capabilities","Access to senior CFOs, controllers and analysts without hiring a full team on payroll.","09")}
      </div><div class="section-visual panorama compact"><img src="${routePhotos.whyPage}" alt="Krakow skyline at golden hour" style="aspect-ratio:3/1;object-fit:cover;object-position:center 42%;"></div><div class="band" style="margin-top:24px">We manage the financial function so owners can make better decisions and grow the business.</div></div></section>`;
}
function teamSection(full=true){
  const teamVisual = full ? routePhotos.teamPage : routePhotos.teamHome;
  return `
  <section class="section ${full?'':'white-band'}" id="team"><div class="container"><div class="kicker">Team</div><h2>A finance team built for SME automated execution.</h2><p class="lead">Bookeon Finance combines senior finance experience with operational accounting, tax, payroll, controlling and automation capability.</p><div class="team-grid" style="margin-top:36px"><article class="team-card"><img src="${team.marcin}" alt="Marcin Leszczyłowski"><div class="team-info"><div class="role">Founder / CEO</div><h3>Marcin Leszczyłowski</h3><p>Senior finance lead supporting SMEs with CFO advisory, financial management, M&A, financing and strategic decision-making.</p></div></article><article class="team-card"><img src="${team.piotr}" alt="Piotr Buszka"><div class="team-info"><div class="role">Founder / CTO</div><h3>Piotr Buszka</h3><p>Technology leader. AI-first business operating models and workflows, governed data and decision systems.</p></div></article><article class="team-card"><img src="${team.nick}" alt="Nick Yerin"><div class="team-info"><div class="role">Senior Manager</div><h3>Nick Yerin</h3><p>Senior management support across finance operations, client delivery and service execution.</p></div></article><article class="team-card"><img src="${team.jerzy}" alt="Jerzy Górski"><div class="team-info"><div class="role">Senior Manager</div><h3>Jerzy Górski</h3><p>Senior management support across finance operations, client delivery and service execution.</p></div></article></div><div class="team-capability-tiles"><article class="team-capability-tile green"><h4>Accounting &<br>Compliance Team</h4></article><article class="team-capability-tile green"><h4>Payroll & HR<br>Administration Team</h4></article><article class="team-capability-tile green"><h4>Controlling & CFO Team</h4></article><article class="team-capability-tile brown"><h4>Tax, Legal & M&A</h4></article><article class="team-capability-tile brown"><h4>Automation &<br>Technology Support</h4></article></div><div class="section-visual horizontal compact"><img src="${teamVisual}" alt="Modern office with city skyline" style="aspect-ratio:3/1;object-fit:cover;object-position:center center;"></div><div class="band">Our model combines senior professionals’ knowledge and experience with scalable automated execution.</div></div></section>`;
}
function contactSection(fullPage=false){
  return `
  <section class="section" id="contact"><div class="container contact-panel"><div class="contact-main"><div class="kicker" style="color:#c6a58b">Contact</div><h2>Let’s build a finance function that helps your business grow.</h2><p>Bookeon Finance — accounting and financial management services built for SMEs.</p><a class="btn btn-primary" style="background:var(--brown)" href="mailto:contact@bookeon.pl">Contact us</a><div class="contact-mini-visual"><img src="${fullPage ? routePhotos.contactZenPage : routePhotos.contactZen}" alt="Brand-palette city skyline"></div></div><div class="contact-side"><div class="contact-visual"><img src="${fullPage ? routePhotos.contactOfficePage : routePhotos.contactOffice}" alt="Night skyline reflections"></div><div class="contact-row"><strong>Email</strong><br>contact@bookeon.pl</div><div class="contact-row"><strong>Phone</strong><br>+48 796 549 530</div><div class="contact-row"><strong>Location</strong><br>Warsaw, Poland</div><div class="contact-row"><strong>Website</strong><br>www.bookeon.pl</div></div></div></section>`;
}
function contactPage(){ return contactSection(true); }
function teamPage(){ return teamSection(true); }
